<script setup lang="ts">
import {computed,onBeforeUnmount,onMounted,reactive,ref,watch} from 'vue';
import type {ReceivableFilters} from '@quote/contracts';
import {ReceivablesController,createReceivablesState,receivableFilterForm,filtersDirty,restoreFilters,accountState,paymentStateLabel,paymentDate,paymentType,paymentReference,PaymentOperations,receivableOperationTarget,beijingToday} from '@quote/receivables-client';
import {beijingTime} from '@quote/archive-client';
import type {PcApi} from '../api';
const props=defineProps<{api:Pick<PcApi,'get'|'post'>;userId:string;admin:boolean;locked?:boolean}>();
const emit=defineEmits<{(e:'busy-changed',value:boolean):void}>();
const state=reactive(createReceivablesState(props.admin)),filters=reactive(receivableFilterForm(state.applied));
const recoveryError=ref(''),recovering=ref(false),notFound=ref(false),acknowledged=ref(false),storageError=ref('');
let operations:Pick<PaymentOperations,'pending'|'mutate'|'check'|'retry'>|null=null;
try{operations=reactive(new PaymentOperations(props.userId,path=>props.api.get(path),(path,body,key)=>props.api.post(path,body,key),{getItem:key=>localStorage.getItem(key),setItem:(key,value)=>localStorage.setItem(key,value),removeItem:key=>localStorage.removeItem(key)}));}catch(e){storageError.value=(e as Error).message;}
const controller=new ReceivablesController(path=>props.api.get(path),(label,path,body)=>{if(!operations)throw new Error(storageError.value||'待核对资料不可用，暂不能提交。');return operations.mutate(label,path,body);},state);
const ownBusy=computed(()=>state.listLoading||state.detailLoading||state.hospitalsLoading||state.working||recovering.value);
const locked=computed(()=>props.locked||ownBusy.value),writeLocked=computed(()=>locked.value||!!operations?.pending||!!storageError.value);
const dirty=computed(()=>filtersDirty(filters,state.applied)),pages=computed(()=>state.page?Math.max(1,Math.ceil(state.page.total/state.page.pageSize)):1);
const ar=computed(()=>state.detail?.receivable),corrected=computed(()=>state.detail?.payments.find(p=>p.id===state.form.correctsPaymentRecordId));
watch(ownBusy,v=>emit('busy-changed',v),{flush:'sync',immediate:true});watch(()=>state.review,()=>{acknowledged.value=false;});
function originalReference(id:string){return paymentReference(state.detail?.payments.find(p=>p.id===id));}
function guard(work:()=>void){try{state.writeError='';work();}catch(e){state.writeError=(e as Error).message;}}
async function query(){if(locked.value)return;await controller.query({...filters} as ReceivableFilters);}
async function reset(){if(locked.value)return;Object.assign(filters,receivableFilterForm(createReceivablesState(props.admin).applied));await query();}
async function back(){if(locked.value)return;restoreFilters(filters,state.applied);await controller.back();}
async function move(n:number){if(locked.value)return;restoreFilters(filters,state.applied);await controller.move(n);}
async function open(id:string){if(locked.value)return;await controller.open(id);}
async function refresh(){if(locked.value)return;if(state.mode==='detail')await controller.open(state.selectedId);else{restoreFilters(filters,state.applied);await controller.back();}}
async function commit(){if(writeLocked.value||!acknowledged.value)return;try{await controller.commit();}catch{/* visible controller error and original pending retained */}}
async function recover(retry=false){if(locked.value||!operations?.pending)return;const original=operations.pending,target=receivableOperationTarget(original);recovering.value=true;recoveryError.value='';try{const status=retry?(await operations.retry(),'committed'):await operations.check();notFound.value=status==='not_found';if(status==='committed'&&target){await controller.open(target);state.notice=state.detail?'原回款操作已确认提交，余额已重新读取。':'原操作已确认提交；最新余额读取失败，请重新加载。';}}catch(e){recoveryError.value=(e as Error).message;}finally{recovering.value=false;}}
onMounted(()=>Promise.all([controller.hospitals(),controller.query(state.applied)]));
onBeforeUnmount(()=>{controller.dispose();emit('busy-changed',false);});
</script>
<template>
 <div class="receivables">
  <p v-if="storageError" class="error" role="alert">{{storageError}}</p>
  <section v-if="operations?.pending" class="recovery" role="status"><strong>「{{operations.pending.label}}」结果待核对</strong><p>原请求已保留。请核对结果，避免重复登记。</p><div class="action-row"><button :disabled="locked" @click="recover()">核对操作结果</button><button v-if="notFound" :disabled="locked" @click="recover(true)">按原请求重新提交</button></div><p v-if="notFound">暂未查到提交结果；重新提交会沿用原金额、日期和操作键。</p><p v-if="recoveryError" class="error" role="alert">{{recoveryError}}</p></section>
  <template v-if="state.mode==='list'">
   <div class="heading"><div><p class="eyebrow">按订单跟进</p><h1>回款台账</h1><p class="muted">医院最终确认形成应收；分次回款按订单分别登记。</p></div><span class="scope">{{admin?'全量业务 · 只读':'默认本人未收齐 · 可查医院旧单'}}</span></div>
   <form class="filters" @submit.prevent="query">
    <label>查看范围<select v-model="filters.ownership" :disabled="locked"><option value="">全部可查看</option><option value="mine">本人负责</option><option value="readonly">其他负责人（只读）</option></select></label>
    <label>医院<select v-model="filters.hospitalId" :disabled="locked"><option value="">全部可查看医院</option><option v-for="h in state.hospitals" :key="h.id" :value="h.id">{{h.name}}</option></select></label>
    <label>回款情况<select v-model="filters.paymentState" :disabled="locked"><option value="">全部回款情况</option><option value="outstanding">全部未收齐</option><option value="unpaid">未收款</option><option value="partial">部分回款</option><option value="settled">已结清</option></select></label>
    <label>到期情况<select v-model="filters.dueState" :disabled="locked"><option value="">全部到期情况</option><option value="upcoming">未到期</option><option value="due">今日到期</option><option value="overdue">逾期未收</option></select></label>
    <label>实际接收日期（起）<input type="date" v-model="filters.receivedFrom" :disabled="locked" /></label><label>实际接收日期（止，含当天）<input type="date" v-model="filters.receivedTo" :disabled="locked" /></label>
    <label>订单号 / 医院<input type="search" v-model="filters.keyword" maxlength="100" :disabled="locked" placeholder="输入完整或部分文字" /></label>
    <div class="filter-actions"><button class="primary" type="submit" :disabled="locked">查询</button><button type="button" :disabled="locked" @click="reset">重置</button></div>
   </form>
   <p v-if="dirty" class="filter-note" role="status">筛选已修改，点击查询后生效；当前结果仍按已查询条件显示。</p>
   <p v-if="state.hospitalsError" class="error" role="alert">医院筛选读取失败：{{state.hospitalsError}} <button :disabled="locked" @click="controller.hospitals()">重试</button></p>
   <p v-if="state.listError" class="error" role="alert">查询失败：{{state.listError}} <button :disabled="locked" @click="back">重新查询</button></p><p v-if="state.listLoading" class="loading" role="status">正在读取回款台账…</p>
   <template v-if="state.page&&!state.listLoading"><div class="result-head"><strong>共 {{state.page.total}} 单应收</strong><span>金额单位：元 · 到期日、单号顺序 · {{beijingTime(state.page.asOf)}}</span></div>
    <div class="table-scroll"><table class="ledger-table"><thead><tr><th>医院 / 订单</th><th>应收</th><th>有效已收</th><th>未收余额</th><th>到期日 / 状态</th><th>负责人</th><th>操作</th></tr></thead><tbody><tr v-for="item in state.page.items" :key="item.id"><td><strong>{{item.hospitalName}}</strong><small>{{item.orderNo}} · 接收 {{item.receivedDate}}</small></td><td>{{item.amount}}</td><td>{{item.paid}}</td><td class="balance">{{item.balance}}</td><td>{{item.dueDate}}<small>{{accountState(item)}}{{accountState(item)===paymentStateLabel(item)?'':' · '+paymentStateLabel(item)}}</small></td><td>{{item.owner.name}}<small>{{item.writable?'订单负责销售':'只读查阅'}}</small></td><td><button class="text-button" :disabled="locked" @click="open(item.id)">{{item.writable?'查看 / 登记 →':'查看 →'}}</button></td></tr><tr v-if="!state.page.items.length"><td class="empty" colspan="7">没有符合当前筛选的应收。</td></tr></tbody></table></div>
    <div class="pagination"><label>每页<select v-model.number="filters.pageSize" :disabled="locked" @change="query"><option :value="20">20 条</option><option :value="50">50 条</option></select></label><span>第 {{state.page.page}} / {{pages}} 页</span><button :disabled="locked||state.page.page<=1" @click="move(state.page!.page-1)">上一页</button><button :disabled="locked||state.page.page>=pages" @click="move(state.page!.page+1)">下一页</button></div>
   </template><p class="footnote">全缺货不产生应收；尚未医院确认及未核实的历史补录不进入台账。</p>
  </template>
  <template v-else>
   <div class="action-row"><button :disabled="locked" @click="back">← 返回台账，保留筛选</button><button :disabled="locked" @click="refresh">载入最新余额</button></div>
   <p v-if="state.detailLoading" class="loading" role="status">正在读取应收和回款记录…</p><p v-if="state.detailError" class="error" role="alert">详情读取失败：{{state.detailError}}</p>
   <p v-if="state.notice" class="filter-note" role="status">{{state.notice}}</p><p v-if="state.writeError" class="error" role="alert">{{state.writeError}}</p>
   <template v-if="ar&&state.detail"><div class="heading detail-heading"><div><p class="eyebrow">{{ar.orderNo}}</p><h1>{{ar.hospitalName}}</h1><p class="muted">实际接收 {{ar.receivedDate}} · 订单负责人 {{ar.owner.name}}</p></div><span class="scope">{{accountState(ar)}}{{ar.writable?'':' · 只读'}}</span></div>
    <div class="facts ledger-facts"><div><span>应收金额 / 元</span><strong>{{ar.amount}}</strong></div><div><span>有效已收 / 元</span><strong>{{ar.paid}}</strong></div><div><span>未收余额 / 元</span><strong>{{ar.balance}}</strong></div><div><span>到期日 · 账期 {{ar.paymentTermDays}} 天</span><strong>{{ar.dueDate}}</strong></div></div>
    <p v-if="!ar.writable" class="filter-note">本单只读，回款登记及误录作废由订单负责销售员处理。</p>
    <div class="account-layout"><section class="records"><div class="section-heading"><h2>回款记录</h2><span class="muted">有效与已作废记录均保留</span></div><p v-if="!state.detail.payments.length" class="muted">暂无回款登记记录。</p>
     <article v-for="p in state.detail.payments" :key="p.id" class="payment-record"><div class="section-heading"><strong>{{p.amount}} 元 <small>{{paymentType(p)}}</small></strong><span>{{p.status==='active'?'有效':'已作废'}}</span></div><dl class="panel-facts"><div><dt>实际回款日期</dt><dd>{{paymentDate(p)}}</dd></div><div><dt>备注</dt><dd>{{p.remark||'—'}}</dd></div><div><dt>原记录人</dt><dd>{{p.recordedByName}}</dd></div><div><dt>原记录时间</dt><dd>{{beijingTime(p.recordedAt)}}</dd></div><template v-if="p.status==='void'"><div><dt>作废原因</dt><dd>{{p.voidReason}}</dd></div><div><dt>作废人 / 时间</dt><dd>{{p.voidedByName}} · {{beijingTime(p.voidedAt)}}</dd></div></template></dl><p v-if="p.correctsPaymentRecordId" class="muted">关联更正原记录：{{originalReference(p.correctsPaymentRecordId)}}</p><div v-if="ar.writable" class="action-row"><button v-if="p.status==='active'" :disabled="writeLocked" @click="state.voidPaymentId=p.id;state.voidReason='';controller.invalidateReview()">作废误录</button><button v-else :disabled="writeLocked||ar.paymentState==='settled'" @click="guard(()=>controller.correct(p.id))">关联原记录重新登记</button></div></article>
    </section>
    <aside v-if="ar.writable" class="payment-entry"><h2>{{state.form.correctsPaymentRecordId?'关联作废记录重录':'登记本次回款'}}</h2><p class="muted">仅登记本单实际收到的一笔款。</p><p v-if="corrected" class="filter-note">原记录 {{paymentReference(corrected)}} <button class="text-button" :disabled="writeLocked" @click="controller.cancelCorrection()">取消关联</button></p>
     <p v-if="ar.paymentState==='settled'" class="filter-note">本单已结清，不能追加正数回款；误录仍可选择原有效记录作废。</p>
     <form @submit.prevent="guard(()=>controller.reviewPayment())"><fieldset :disabled="writeLocked||ar.paymentState==='settled'||!!state.review"><label>实际回款金额 / 元<input v-model="state.form.amount" inputmode="decimal" autocomplete="off" placeholder="如 1000.00" @input="controller.invalidateReview()" /></label><label v-if="!(corrected?.recordType==='historical_opening'&&corrected.paidDate===null)">实际回款日期<input v-model="state.form.paidDate" type="date" :max="beijingToday()" @input="controller.invalidateReview()" /></label><p v-else class="muted">原历史累计回款日期未知，本次更正继续保留未知。</p><label>备注（可选）<textarea v-model="state.form.remark" maxlength="500" @input="controller.invalidateReview()"></textarea></label><small>实际日期与录入日期分别保存，不以今天代替实际日期。</small><button type="submit" class="primary">复核本次回款</button></fieldset></form>
     <form v-if="state.voidPaymentId" class="void-entry" @submit.prevent="guard(()=>controller.reviewVoid())"><h2>作废误录回款</h2><p class="muted">仅更正台账，不表示发生实际退款。</p><label>作废原因<textarea v-model="state.voidReason" maxlength="500" :disabled="writeLocked||!!state.review" @input="controller.invalidateReview()"></textarea></label><button :disabled="writeLocked||!!state.review" type="submit">复核作废</button><button type="button" :disabled="writeLocked" @click="state.voidPaymentId='';controller.invalidateReview()">取消作废</button></form>
    </aside></div>
   </template>
  </template>
  <div v-if="state.review" class="review-overlay" @click.self="!state.working&&controller.invalidateReview()"><section class="review-dialog" role="dialog" aria-modal="true" aria-labelledby="payment-review-title"><p class="eyebrow">提交前复核</p><h2 id="payment-review-title">{{state.review.kind==='payment'?'登记本次回款':'作废原回款'}}</h2><dl class="review-facts"><dt>医院 / 订单</dt><dd>{{state.review.hospitalName}}<br>{{state.review.orderNo}}</dd><dt>金额 / 实际日期</dt><dd>{{state.review.kind==='payment'?state.review.body.amount:state.review.payment?.amount}} 元 · {{state.review.kind==='payment'?(state.review.body.paidDate||'日期未知（历史累计）'):paymentDate(state.review.payment!)}}</dd><template v-if="state.review.kind==='payment'"><dt>备注</dt><dd>{{state.review.body.remark||'—'}}</dd><template v-if="state.review.body.correctsPaymentRecordId"><dt>关联原记录</dt><dd>{{originalReference(String(state.review.body.correctsPaymentRecordId))}}</dd></template></template><template v-else><dt>作废原因</dt><dd>{{state.review.body.reason}}</dd><dt>原记录人 / 时间</dt><dd>{{state.review.payment?.recordedByName}} · {{beijingTime(state.review.payment?.recordedAt)}}</dd></template><dt>未收余额变化</dt><dd>{{state.review.balanceBefore}} → {{state.review.balanceAfter}} 元</dd></dl><label class="review-ack"><input type="checkbox" v-model="acknowledged" :disabled="state.working" />{{state.review.kind==='payment'?'已核对订单、金额与实际日期，这笔款未重复登记。':'已核对原记录与作废原因；作废仅更正台账。'}}</label><div class="action-row"><button :disabled="state.working" @click="controller.invalidateReview()">返回修改</button><button class="primary" :disabled="writeLocked||!acknowledged" @click="commit">{{state.working?'正在提交…':state.review.kind==='payment'?'确认登记':'确认作废'}}</button></div></section></div>
 </div>
</template>
<style scoped>
.ledger-table{min-width:980px}.ledger-table td:first-child{min-width:220px}.balance{font-weight:600;font-variant-numeric:tabular-nums}.ledger-facts strong{font-size:23px}.account-layout{display:grid;grid-template-columns:minmax(0,1fr) 330px;gap:44px;padding-top:30px}.account-layout:has(>.records:last-child){grid-template-columns:1fr}.section-heading{display:flex;justify-content:space-between;gap:16px;align-items:start}.section-heading .muted{font-size:11px}.payment-record{padding:22px 0;border-bottom:1px solid #dfe7e1}.payment-record:first-of-type{padding-top:8px}.payment-record .panel-facts{grid-template-columns:1fr}.payment-entry{border-left:1px solid #dfe7e1;padding-left:28px}.payment-entry fieldset{border:0;padding:0;margin:24px 0;display:grid;gap:18px;min-width:0}.payment-entry textarea{width:100%;height:88px;border:1px solid #ccd8d1;border-radius:4px;resize:vertical;font:inherit;padding:10px}.payment-entry fieldset:disabled{opacity:.6}.void-entry{border-top:1px solid #dfe7e1;margin-top:30px;padding-top:22px}.void-entry label{margin:18px 0}.void-entry button{margin-right:8px}.action-row{display:flex;gap:10px;flex-wrap:wrap}.recovery{padding:20px 0;margin:0 0 25px;border-top:2px solid #a27545;border-bottom:1px solid #dfe7e1;font-size:13px;line-height:1.7}.review-overlay{position:fixed;inset:0;background:#15251b66;display:flex;align-items:center;justify-content:center;padding:24px;z-index:20}.review-dialog{background:#fff;padding:30px;max-width:620px;width:100%;max-height:90vh;overflow:auto;animation:enter .15s ease-out}.review-facts{display:grid;grid-template-columns:130px minmax(0,1fr);gap:16px 20px;font-size:13px;line-height:1.7;margin:25px 0}.review-facts dt{color:#74837a}.review-facts dd{margin:0;white-space:pre-wrap;overflow-wrap:anywhere}.review-ack{display:flex;align-items:start;gap:10px;line-height:1.7;margin:24px 0}.review-ack input{width:18px;height:18px;flex-shrink:0}.review-dialog .action-row{justify-content:flex-end}@media(max-width:850px){.account-layout{grid-template-columns:1fr;gap:30px}.payment-entry{padding:24px 0 0;border-left:0;border-top:1px solid #dfe7e1}.review-overlay{padding:16px}.review-dialog{padding:24px}.review-facts{grid-template-columns:100px minmax(0,1fr);gap:14px}.ledger-facts strong{font-size:20px}}
</style>
